    "question": "In any simple undirected graph with n vertices, what does the Handshake Lemma state?",
    "options": {
      "A": "The sum of all vertex degrees equals twice the number of edges.",
      "B": "The number of vertices of odd degree is always even.",
      "C": "The maximum degree is at most n‑1.",
      "D": "Every vertex is adjacent to at least one other vertex."
    },
    "correct_answer": "A",
    "explanation": "The Handshake Lemma says Σ deg(v)=2|E|, because each edge contributes to the degree of its two endpoints.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following is an equivalent condition for a graph to be bipartite?",
    "options": {
      "A": "It contains no cycles of odd length.",
      "B": "Its chromatic number is exactly three.",
      "C": "Every vertex has degree at most two.",
      "D": "It has a Hamiltonian path."
    },
    "correct_answer": "A",
    "explanation": "A graph is bipartite iff it has no odd‑length cycles; any odd cycle forces two adjacent vertices into the same part.",
    "difficulty": "Medium"
  },
  {
    "question": "A connected undirected graph has an Eulerian circuit if and only if:",
    "options": {
      "A": "All vertices have even degree.",
      "B": "Exactly two vertices have odd degree.",
      "C": "It contains a Hamiltonian cycle.",
      "D": "Its maximum degree equals the number of vertices minus one."
    },
    "correct_answer": "A",
    "explanation": "Euler’s theorem: a connected graph admits a closed trail using every edge exactly once precisely when every vertex degree is even.",
    "difficulty": "Medium"
  },
  {
    "question": "For the adjacency matrix A of a simple graph G, the entry (A^k)_{ij} equals:",
    "options": {
      "A": "The number of distinct walks of length k from vertex i to vertex j.",
      "B": "The number of distinct paths of length k from vertex i to vertex j.",
      "C": "1 if there is a walk of length k from i to j, otherwise 0.",
      "D": "The degree of vertex i multiplied by the degree of vertex j."
    },
    "correct_answer": "A",
    "explanation": "Powers of the adjacency matrix count walks (not necessarily simple paths); (A^k)_{ij} gives the total number of length‑k walks from i to j.",
    "difficulty": "Medium"
  },
  {
    "question": "Which of the following graphs is non‑planar?",
    "options": {
      "A": "The complete bipartite graph K_{3,3}.",
      "B": "A cycle C_6.",
      "C": "A tree with 10 vertices.",
      "D": "The wheel graph W_5."
    },
    "correct_answer": "A",
    "explanation": "K_{3,3} contains a subdivision of K_{3,3} itself, which by Kuratowski's theorem is a minimal non‑planar graph; the others are planar.",
    "difficulty": "Medium"
  }
]
